const SV_L=(x1,y1,x2,y2,col='#5C6577',w=2,ex='')=>`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${col}" stroke-width="${w}" stroke-linecap="round" ${ex}/>`;
