/* computed points of f on [t0,t1], mapped to x in [x0,x1] and y = yc - k*f */
const SV_pts=(f,t0,t1,x0,x1,yc,k,n)=>{let p=[];for(let i=0;i<=n;i++){const t=t0+(t1-t0)*i/n;p.push(`${(x0+(x1-x0)*i/n).toFixed(1)},${(yc-k*f(t)).toFixed(1)}`)}return p};
const SV_curve=(f,t0,t1,x0,x1,yc,k,col,w=4,n=120,ex='')=>`<polyline points="${SV_pts(f,t0,t1,x0,x1,yc,k,n).join(' ')}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linejoin="round" stroke-linecap="round" ${ex}/>`;
/* the area between f and the axis y = yc */
const SV_area=(f,t0,t1,x0,x1,yc,k,col,op=.3,n=80)=>`<polygon points="${x0},${yc} ${SV_pts(f,t0,t1,x0,x1,yc,k,n).join(' ')} ${x1},${yc}" fill="${col}" fill-opacity="${op}" stroke="none"/>`;
const SV_stems=(v,x0,dx,yc,k,col,r=7)=>v.map((q,i)=>{const x=x0+i*dx,y=yc-k*q;return SV_L(x,yc,x,y,col,4)+`<circle cx="${x}" cy="${y.toFixed(1)}" r="${r}" fill="${col}"/>`}).join('');
