function EXTRA(R,ICON){
 /* hook: three tones added into one symbol, and the receiver taking each one back with one inner product (computed points) */
 ICON.svTones=(x,y)=>`<g transform="translate(${x-190} ${y-80})">${SV_box(0,0,380,160,{fill:'#FFFFFF',st:BLU,sw:3,r:18})}${SV_T(20,36,'three tones, one symbol',{fs:24,fw:800,fill:BLU})}${SV_L(24,102,356,102,SV_AX,2)}${SV_curve(t=>Math.cos(2*SV_PI*t),0,1,24,356,102,40,BLU,4)}${SV_curve(t=>0.6*Math.cos(4*SV_PI*t),0,1,24,356,102,40,ORG,4)}${SV_curve(t=>0.8*Math.cos(6*SV_PI*t),0,1,24,356,102,40,GRN,4)}</g>`;
 ICON.svRx=(x,y)=>`<g transform="translate(${x-190} ${y-80})">${SV_box(0,0,380,160,{fill:'#FFFFFF',st:ORG,sw:3,r:18})}${SV_T(20,36,'one inner product per tone',{fs:24,fw:800,fill:ORG})}${SV_L(16,100,124,100,SV_AX,2)}${SV_curve(SV_sum,0,1,16,124,100,18,INK,3)}${SV_arrow(130,100,154,100,INK,3,12)}${SV_box(158,74,92,52,{fill:'#E3FAF1',st:ACC,sw:3,r:10})}${SV_T(204,108,'⟨x, φₖ⟩',{fs:22,fw:800,a:'middle'})}${SV_arrow(256,100,280,100,INK,3,12)}${SV_L(284,136,368,136,SV_AX,2)}${[BLU,ORG,GRN].map((col,k)=>SV_L(298+k*30,136,298+k*30,136-70*SV_TONES[k],col,5)+`<circle cx="${298+k*30}" cy="${(136-70*SV_TONES[k]).toFixed(1)}" r="7" fill="${col}"/>`).join('')}</g>`;
 /* recap pictures: each fills most of its card (about 420 × 330) */
 ICON.svProjI=(x,y)=>`<g transform="translate(${x-210} ${y-165})">${SV_proj(20,270,410,270,40,28)}</g>`;
 ICON.svBarsI=(x,y)=>`<g transform="translate(${x-210} ${y-165})">${SV_L(0,290,420,290,SV_AX,3)}${SV_ERR.map((e,i)=>`<rect x="${12+i*82}" y="${(290-220*e/SV_ERR[0]).toFixed(1)}" width="64" height="${(220*e/SV_ERR[0]).toFixed(1)}" rx="5" fill="${ORG}" fill-opacity=".8"/>`+SV_T(44+i*82,(280-220*e/SV_ERR[0]).toFixed(1),e.toFixed(2),{fs:24,fw:800,a:'middle'})).join('')}${SV_T(210,326,'ε(N) after n = 1, 3, 5, 7, 9',{fs:24,fw:700,a:'middle',fill:SV_GREY})}</g>`;
 ICON.svParseI=(x,y)=>{const W=[1/9,1/12,1/180].map(v=>400*v/(1/5)),C=[BLU,ORG,MAG];let xx=10,s='';W.forEach((w,i)=>{s+=`<rect x="${xx.toFixed(1)}" y="60" width="${w.toFixed(1)}" height="170" fill="${C[i]}" fill-opacity=".8"/>`;xx+=w});
  return `<g transform="translate(${x-210} ${y-165})">${SV_T(210,36,'energy of t² on [0, 1]',{fs:28,fw:800,a:'middle'})}${s}<rect x="10" y="60" width="400" height="170" fill="none" stroke="${INK}" stroke-width="3"/>${SV_T(121,158,'1/9',{fs:36,fw:800,a:'middle',fill:'#FFFFFF'})}${SV_T(305,158,'1/12',{fs:36,fw:800,a:'middle',fill:'#FFFFFF'})}${SV_L(405,234,405,262,MAG,3)}${SV_T(410,286,'1/180',{fs:26,fw:800,a:'end',fill:MAG})}${SV_T(10,322,'sum = 1/5 = E',{fs:32,fw:800,fill:GRN})}</g>`};
}
